-- Accepted admin revocations remain queued until their independent event is acknowledged
CREATE TABLE admin_revocations (id TEXT PRIMARY KEY NOT NULL, action_id TEXT UNIQUE, event TEXT NOT NULL, acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN (0,1)), code TEXT, created_at INTEGER NOT NULL);
CREATE INDEX admin_revocations_pending ON admin_revocations(acknowledged,created_at,id);
CREATE TRIGGER admin_revocations_immutable BEFORE UPDATE ON admin_revocations WHEN NEW.id IS NOT OLD.id OR NEW.action_id IS NOT OLD.action_id OR NEW.event IS NOT OLD.event OR NEW.created_at IS NOT OLD.created_at OR NEW.acknowledged<OLD.acknowledged BEGIN SELECT RAISE(ABORT,'revocation_immutable'); END;
ALTER TABLE admin_revocations ADD COLUMN metadata_bytes INTEGER GENERATED ALWAYS AS (length(CAST(json_array(id,action_id,event,acknowledged,code,created_at) AS BLOB))) VIRTUAL;
CREATE TRIGGER admin_revocations_charge_insert AFTER INSERT ON admin_revocations BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes+NEW.metadata_bytes,metadata_rows=metadata_rows+1 WHERE scope='global'; END;
CREATE TRIGGER admin_revocations_closed_insert BEFORE INSERT ON admin_revocations WHEN COALESCE((SELECT state FROM recovery_control WHERE id=1),'closed') NOT IN ('open','restoring') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER admin_revocations_charge_delete AFTER DELETE ON admin_revocations BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes-OLD.metadata_bytes,metadata_rows=metadata_rows-1 WHERE scope='global'; END;
CREATE TRIGGER admin_revocations_closed_delete BEFORE DELETE ON admin_revocations WHEN COALESCE((SELECT state FROM recovery_control WHERE id=1),'closed') NOT IN ('open','restoring') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
CREATE TRIGGER admin_revocations_charge_update AFTER UPDATE ON admin_revocations BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes-OLD.metadata_bytes+NEW.metadata_bytes WHERE scope='global'; END;
CREATE TRIGGER admin_revocations_closed_update BEFORE UPDATE ON admin_revocations WHEN COALESCE((SELECT state FROM recovery_control WHERE id=1),'closed') NOT IN ('open','restoring') BEGIN SELECT RAISE(ABORT,'service_closed'); END;
-- Migration reconciliation records observation time, never an invented historical acknowledgment
-- Generate canonical opaque IDs with 128 random bits using SQLite's built-in random source
-- Correlate each recursive seed with its source row so SQLite cannot reuse one ID across rows
-- The non-flattened row subquery keeps the stored ID and JSON intent identical
INSERT INTO admin_revocations(id,event,created_at) SELECT intent,json_object('version',1,'kind','operator-revoked','intentId',intent,'operatorId',id,'sessionEpoch',revision,'timestamp',unixepoch()*1000),unixepoch()*1000 FROM (SELECT *,(WITH RECURSIVE opaque(n,value) AS (SELECT 0,substr(operators.id,1,0) UNION ALL SELECT n+1,value||substr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_',1+(random()&63),1) FROM opaque WHERE n<21) SELECT value||substr('AQgw',1+(random()&3),1) FROM opaque WHERE n=21 AND operators.id IS NOT NULL) AS intent FROM operators WHERE state='revoked' LIMIT -1 OFFSET 0);
INSERT INTO admin_revocations(id,event,created_at) SELECT intent,json_object('version',1,'kind','invitation-revoked','intentId',intent,'invitationId',id,'operatorId',created_by,'sessionEpoch',revision,'timestamp',unixepoch()*1000),unixepoch()*1000 FROM (SELECT *,(WITH RECURSIVE opaque(n,value) AS (SELECT 0,substr(admin_invitations.id,1,0) UNION ALL SELECT n+1,value||substr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_',1+(random()&63),1) FROM opaque WHERE n<21) SELECT value||substr('AQgw',1+(random()&3),1) FROM opaque WHERE n=21 AND admin_invitations.id IS NOT NULL) AS intent FROM admin_invitations WHERE state='cancelled' LIMIT -1 OFFSET 0);
INSERT INTO recovery_source_stats SELECT 'admin_revocations',COUNT(*),COALESCE(SUM(length(CAST(json_array(id,action_id,event,acknowledged,code,created_at) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(id,action_id,event,acknowledged,code,created_at) AS BLOB))),0) FROM admin_revocations;
CREATE TRIGGER recovery_admin_revocations_insert AFTER INSERT ON admin_revocations BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+length(CAST(json_array(NEW.id,NEW.action_id,NEW.event,NEW.acknowledged,NEW.code,NEW.created_at) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.id,NEW.action_id,NEW.event,NEW.acknowledged,NEW.code,NEW.created_at) AS BLOB))) WHERE name='admin_revocations'; END;
CREATE TRIGGER recovery_admin_revocations_delete AFTER DELETE ON admin_revocations BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes-length(CAST(json_array(OLD.id,OLD.action_id,OLD.event,OLD.acknowledged,OLD.code,OLD.created_at) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.id,OLD.action_id,OLD.event,OLD.acknowledged,OLD.code,OLD.created_at) AS BLOB))) WHERE name='admin_revocations'; END;
CREATE TRIGGER recovery_admin_revocations_update AFTER UPDATE ON admin_revocations BEGIN UPDATE recovery_source_stats SET bytes=bytes-length(CAST(json_array(OLD.id,OLD.action_id,OLD.event,OLD.acknowledged,OLD.code,OLD.created_at) AS BLOB))+length(CAST(json_array(NEW.id,NEW.action_id,NEW.event,NEW.acknowledged,NEW.code,NEW.created_at) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.id,NEW.action_id,NEW.event,NEW.acknowledged,NEW.code,NEW.created_at) AS BLOB))) WHERE name='admin_revocations'; END;

